internal static class UrlBuilder
{
    public static string QueryString(params (string Name, string? Value)[] values)
    {
        var parts = new List<string>();
        foreach (var (name, value) in values)
        {
            var normalizedValue = value?.Trim();
            if (!string.IsNullOrWhiteSpace(normalizedValue))
            {
                parts.Add($"{Uri.EscapeDataString(name)}={Uri.EscapeDataString(normalizedValue)}");
            }
        }

        return parts.Count == 0 ? string.Empty : "?" + string.Join("&", parts);
    }
}

internal static class JsonOutput
{
    private static readonly JsonSerializerOptions PrettyOptions = new() { WriteIndented = true };
    private static readonly JsonWriterOptions MachineReadableOptions = new() { Indented = true };

    public static string Pretty(string raw)
    {
        return TryPretty(raw, out var pretty) ? pretty : raw;
    }

    public static string MachineReadableUntrustedJobTrackData(string raw)
    {
        using var stream = new MemoryStream();
        using (var writer = new Utf8JsonWriter(stream, MachineReadableOptions))
        {
            writer.WriteStartObject();
            writer.WriteBoolean("untrusted", true);
            writer.WriteString("source", "JobTrack API");
            writer.WriteString("boundaryStart", UntrustedJobTrackOutput.BoundaryStart);
            writer.WriteString("notice", UntrustedJobTrackOutput.BoundaryNotice);
            writer.WriteString("boundaryEnd", UntrustedJobTrackOutput.BoundaryEnd);
            writer.WritePropertyName("data");
            WriteJsonData(writer, raw);
            writer.WriteEndObject();
        }

        return Encoding.UTF8.GetString(stream.ToArray());
    }

    private static void WriteJsonData(Utf8JsonWriter writer, string raw)
    {
        if (string.IsNullOrWhiteSpace(raw))
        {
            writer.WriteNullValue();
            return;
        }

        try
        {
            using var doc = JsonDocument.Parse(raw);
            doc.RootElement.WriteTo(writer);
        }
        catch (JsonException)
        {
            writer.WriteStringValue(raw);
        }
    }

    public static bool TryPretty(string raw, out string pretty)
    {
        if (string.IsNullOrWhiteSpace(raw))
        {
            pretty = raw;
            return true;
        }

        try
        {
            using var doc = JsonDocument.Parse(raw);
            pretty = JsonSerializer.Serialize(doc.RootElement, PrettyOptions);
            return true;
        }
        catch (JsonException)
        {
            pretty = raw;
            return false;
        }
    }
}

internal static class TaskJson
{
    // Accept common API envelope and field aliases so the CLI remains tolerant
    // across current JobTrack responses and earlier scaffold contract drafts.
    private static readonly string[] TaskArrayPropertyNames = ["items", "tasks", "data", "value"];
    private static readonly string[] TaskObjectPropertyNames = ["task", "data", "item"];
    private static readonly string[] ShortCodePropertyNames = ["shortCode", "short_code", "code", "id"];
    private static readonly string[] TitlePropertyNames = ["title", "name"];
    private static readonly string[] StatusPropertyNames = ["status", "state"];
    private static readonly string[] ProjectPropertyNames = ["projectId", "project", "project_id"];

    public static IReadOnlyList<TaskRow>? ReadTaskRows(string raw)
    {
        using var doc = TryParse(raw);
        if (doc is null)
        {
            return null;
        }

        var source = TaskArrayOrNull(doc.RootElement);
        if (source is null)
        {
            return null;
        }

        var rows = new List<TaskRow>();
        foreach (var item in source.Value.EnumerateArray())
        {
            var row = ReadTaskRowOrNull(item);
            if (row is null)
            {
                return null;
            }

            rows.Add(row);
        }

        return rows;
    }

    public static IReadOnlyList<TaskDetail>? ReadTaskDetails(string raw)
    {
        using var doc = TryParse(raw);
        if (doc is null)
        {
            return null;
        }

        var task = TaskObjectOrNull(doc.RootElement);
        if (task is null)
        {
            return null;
        }

        var details = new List<TaskDetail>();
        AddIfPresent(details, "Short code", ReadString(task.Value, ShortCodePropertyNames));
        AddIfPresent(details, "Title", ReadString(task.Value, TitlePropertyNames));
        AddIfPresent(details, "Status", ReadString(task.Value, StatusPropertyNames));
        AddIfPresent(details, "Project", ReadString(task.Value, ProjectPropertyNames));
        AddIfPresent(details, "Description", ReadString(task.Value, "description"));
        return details.Count == 0 ? null : details;
    }

    private static JsonDocument? TryParse(string raw)
    {
        try
        {
            return JsonDocument.Parse(raw);
        }
        catch (JsonException)
        {
            return null;
        }
    }

    private static JsonElement? TaskArrayOrNull(JsonElement root)
    {
        if (root.ValueKind == JsonValueKind.Array)
        {
            return root;
        }

        if (root.ValueKind != JsonValueKind.Object)
        {
            return null;
        }

        foreach (var propertyName in TaskArrayPropertyNames)
        {
            if (root.TryGetProperty(propertyName, out var property) && property.ValueKind == JsonValueKind.Array)
            {
                return property;
            }
        }

        return null;
    }

    private static TaskRow? ReadTaskRowOrNull(JsonElement item)
    {
        var shortCode = ReadString(item, ShortCodePropertyNames);
        var title = ReadString(item, TitlePropertyNames);
        var status = ReadString(item, StatusPropertyNames);
        return string.IsNullOrEmpty(shortCode) && string.IsNullOrEmpty(title) && string.IsNullOrEmpty(status)
            ? null
            : new TaskRow(shortCode, title, status);
    }

    private static JsonElement? TaskObjectOrNull(JsonElement root)
    {
        if (root.ValueKind == JsonValueKind.Object)
        {
            foreach (var propertyName in TaskObjectPropertyNames)
            {
                if (root.TryGetProperty(propertyName, out var property) && property.ValueKind == JsonValueKind.Object)
                {
                    return property;
                }
            }

            return root;
        }

        return null;
    }

    private static string ReadString(JsonElement item, params string[] names)
    {
        if (item.ValueKind != JsonValueKind.Object)
        {
            return string.Empty;
        }

        foreach (var name in names)
        {
            if (!item.TryGetProperty(name, out var value))
            {
                continue;
            }

            return value.ValueKind switch
            {
                JsonValueKind.String => value.GetString() ?? string.Empty,
                JsonValueKind.Number => value.GetRawText(),
                JsonValueKind.True => "true",
                JsonValueKind.False => "false",
                _ => value.GetRawText(),
            };
        }

        return string.Empty;
    }

    private static void AddIfPresent(ICollection<TaskDetail> details, string label, string value)
    {
        if (!string.IsNullOrWhiteSpace(value))
        {
            details.Add(new TaskDetail(label, value));
        }
    }
}

